size_t pqcp_channel_operation_plan_conformance_count(void)
{
	return ARRAY_SIZE(channel_plan_catalog);
}

int pqcp_channel_operation_plan_conformance_get(
	size_t index,
	struct pqcp_channel_operation_plan_case *test_case)
{
	if (index >= ARRAY_SIZE(channel_plan_catalog) ||
	    test_case == NULL) {
		return -EINVAL;
	}
	*test_case = channel_plan_catalog[index];
	test_case->schema_version =
		PQCP_OPERATION_PLAN_CONFORMANCE_SCHEMA_VERSION;
	test_case->case_id = PQCP_OPERATION_PLAN_CASE_ID(
		PQCP_OPERATION_PLAN_CONFORMANCE_CHANNEL,
		test_case->scenario, test_case->context.state,
		test_case->context.control);
	return 0;
}

int pqcp_channel_operation_plan_conformance_find(
	enum pqcp_operation_plan_scenario scenario,
	enum pqcp_channel_policy_state state,
	enum pqcp_channel_control_kind control,
	struct pqcp_channel_operation_plan_case *test_case)
{
	if (scenario < PQCP_OPERATION_PLAN_SCENARIO_BASELINE ||
	    scenario >= PQCP_OPERATION_PLAN_SCENARIO_COUNT ||
	    state < PQCP_CHANNEL_POLICY_NEW ||
	    state > PQCP_CHANNEL_POLICY_TERMINATED ||
	    control < PQCP_CHANNEL_CONTROL_NONE ||
	    control >= PQCP_CHANNEL_CONTROL_KIND_COUNT ||
	    test_case == NULL) {
		return -EINVAL;
	}
	for (size_t index = 0U;
	     index < ARRAY_SIZE(channel_plan_catalog); ++index) {
		if (channel_plan_catalog[index].scenario == scenario &&
		    channel_plan_catalog[index].context.state == state &&
		    channel_plan_catalog[index].context.control == control) {
			return pqcp_channel_operation_plan_conformance_get(
				index, test_case);
		}
	}
	return -ENOENT;
}

static uint64_t fingerprint_u32(uint64_t value, uint32_t word)
{
	for (size_t index = 0U; index < sizeof(word); ++index) {
		value ^= (uint8_t)(word >> (index * 8U));
		value *= UINT64_C(1099511628211);
	}
	return value;
}

static uint64_t fingerprint_case(
	uint64_t value,
	const struct pqcp_channel_operation_plan_case *test_case)
{
	value = fingerprint_u32(value, (uint32_t)test_case->schema_version);
	value = fingerprint_u32(value, (uint32_t)test_case->case_id);
	value = fingerprint_u32(value, (uint32_t)test_case->scenario);
	value = fingerprint_u32(value, (uint32_t)test_case->context.state);
	value = fingerprint_u32(value, (uint32_t)test_case->context.path_condition);
	value = fingerprint_u32(value, (uint32_t)test_case->context.fault_condition);
	value = fingerprint_u32(value, (uint32_t)test_case->context.control);
	value = fingerprint_u32(value, (uint32_t)test_case->disposition);
	value = fingerprint_u32(value, (uint32_t)test_case->next_state);
	value = fingerprint_u32(value, (uint32_t)test_case->probe_timeout_ms);
	value = fingerprint_u32(value, (uint32_t)test_case->migration_hysteresis_bps);
	value = fingerprint_u32(value, (uint32_t)test_case->retry_limit);
	value = fingerprint_u32(value, (uint32_t)test_case->retry_delay_ms);
	value = fingerprint_u32(value, (uint32_t)test_case->reason_mask);
	value = fingerprint_u32(value, (uint32_t)test_case->expected_error);
	return value;
}

int pqcp_channel_operation_plan_conformance_fingerprint(
	uint64_t *fingerprint)
{
	uint64_t value = UINT64_C(14695981039346656037);
	struct pqcp_channel_operation_plan_case test_case;

	if (fingerprint == NULL) {
		return -EINVAL;
	}
	for (size_t index = 0U;
	     index < ARRAY_SIZE(channel_plan_catalog); ++index) {
		int ret = pqcp_channel_operation_plan_conformance_get(
			index, &test_case);

		if (ret != 0) {
			return ret;
		}
		value = fingerprint_case(value, &test_case);
	}
	*fingerprint = value;
	return 0;
}

int pqcp_channel_operation_plan_conformance_audit(void)
{
	if (ARRAY_SIZE(channel_plan_catalog) !=
	    PQCP_CHANNEL_OPERATION_PLAN_CONFORMANCE_CASES) {
		return -EBADMSG;
	}
	for (size_t index = 0U;
	     index < ARRAY_SIZE(channel_plan_catalog); ++index) {
		struct pqcp_channel_operation_plan_case test_case;
		struct pqcp_channel_operation_plan actual;
		int ret;

		ret = pqcp_channel_operation_plan_conformance_get(
			index, &test_case);
		if (ret != 0) {
			return ret;
		}
		ret = pqcp_channel_operation_plan(
			&test_case.context, &actual);
		if (ret != 0 ||
		    test_case.schema_version !=
			    PQCP_OPERATION_PLAN_CONFORMANCE_SCHEMA_VERSION ||
		    test_case.case_id != PQCP_OPERATION_PLAN_CASE_ID(
			    PQCP_OPERATION_PLAN_CONFORMANCE_CHANNEL,
			    test_case.scenario, test_case.context.state,
			    test_case.context.control) ||
		    actual.disposition != test_case.disposition ||
		    actual.next_state != test_case.next_state ||
		    actual.probe_timeout_ms !=
			    test_case.probe_timeout_ms ||
		    actual.migration_hysteresis_bps !=
			    test_case.migration_hysteresis_bps ||
		    actual.retry_limit != test_case.retry_limit ||
		    actual.retry_delay_ms !=
			    test_case.retry_delay_ms ||
		    actual.reason_mask != test_case.reason_mask ||
		    actual.error != test_case.expected_error) {
			return -EBADMSG;
		}
	}
	return 0;
}
